/* An imagined inn menu; original modern adaptations, with separate source ratings. */
'use strict';
(() => {
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const checked=new Set();
 const checkAttrs=(id,kind,index)=>{const key=id+':'+kind+':'+index;return `data-recipe-check="${esc(key)}"${checked.has(key)?' checked':''}`};
 let lang='he';const t=(he,en)=>lang==='he'?he:en,h=v=>esc(typeof v==='object'&&v?v[lang]||v.en||'':v),D=()=>window.RECIPE_CONTENT;
 const outside=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${h(label)} ↗<span class="sr-only">${t(' (נפתח בלשונית חדשה)',' (opens in a new tab)')}</span></a>`;
 const art={
 'bishops-bread-soup':`<ellipse cx="180" cy="208" rx="141" ry="41" fill="#d9cbb3"/><ellipse cx="180" cy="197" rx="135" ry="44" fill="#faf5e9" stroke="#173565" stroke-width="3"/><path d="M64 140q5 100 116 106t116-106z" fill="#e9f0f3" stroke="#173565" stroke-width="3"/><ellipse cx="180" cy="140" rx="117" ry="52" fill="#f9edd2" stroke="#173565" stroke-width="3"/><ellipse cx="180" cy="145" rx="105" ry="42" fill="#cdaa57"/><path d="M101 134l39-17 29 29-45 18zM184 123l43-15 24 35-44 16zM171 155l36 6-15 23-40-7z" fill="#e7ca8b" stroke="#956838" stroke-width="3"/><path d="M140 65q-14 18 0 32m42-53q-14 22 0 36m40-20q-14 17 0 29" stroke="#7f8f97" stroke-width="3" fill="none" stroke-linecap="round"/><ellipse cx="268" cy="147" rx="15" ry="5" fill="#dfc579"/>`,
 'tahini-walnut-loaf':`<ellipse cx="181" cy="214" rx="137" ry="30" fill="#d7c5a6"/><path d="M73 174V110q19-45 98-35l80 10q40 10 40 39v64l-93 36z" fill="#b88443" stroke="#67472e" stroke-width="3"/><path d="M73 123q12-46 66-44 60-4 63 55v90l-129-46z" fill="#e2be78" stroke="#67472e" stroke-width="3"/><path d="M91 123q16-27 45-25 41-1 49 39v61l-94-31z" fill="#eed7a1"/><path d="M202 134l89-13M226 92l-11 22m43-15-12 20" stroke="#835528" stroke-width="4"/><path d="M111 126l13 2-3 14-13-5zm41 9 11-4 8 12-15 7zm-26 26 11-5 9 10-13 6z" fill="#97703f"/><path d="M48 189q-17-28-30-5-6 15 13 22 18 6 17-17zm241 26q-15-26-28-4-3 16 12 23 17 1 16-19z" fill="#a67743" stroke="#725134" stroke-width="2"/>`,
 'warm-brie':`<ellipse cx="180" cy="192" rx="130" ry="72" fill="#ddcdb5"/><ellipse cx="180" cy="177" rx="130" ry="72" fill="#faf5e9" stroke="#173565" stroke-width="3"/><ellipse cx="180" cy="177" rx="105" ry="52" fill="none" stroke="#b9a986"/><path d="M115 148q0-47 72-47t72 47v42q-18 25-70 28t-74-23z" fill="#eed493" stroke="#4a3b29" stroke-width="2"/><ellipse cx="187" cy="145" rx="72" ry="44" fill="#fff4cd" stroke="#6f5837" stroke-width="2"/><path d="M176 101l21 83 62-39-35 46-27-7 1 34-55-22" fill="#edc65f" stroke="#9c743b"/><path d="M173 122l27 17-11 29" fill="none" stroke="#cc8b27" stroke-width="6" stroke-linecap="round"/><path d="M102 183q-40-55-63-18-10 32 35 42z" fill="#732b51"/><path d="M91 188q-23-36-39-15-4 15 24 24z" fill="#cc7b89"/><path d="M240 191l43-29 30 34-41 30z" fill="#af783e" stroke="#664826" stroke-width="3"/><path d="M195 120l14-39m-6 21 18-11m-20 14-10-12" stroke="#456648" stroke-width="3" fill="none"/>`,
 'lemon-cream-fish':`<rect x="44" y="83" width="275" height="153" rx="32" fill="#ddc9a4"/><rect x="35" y="72" width="290" height="157" rx="30" fill="#fdf8ec" stroke="#173565" stroke-width="4"/><rect x="59" y="93" width="242" height="114" rx="22" fill="#e9d59e"/><path d="M90 122q63-21 148 8l-15 51q-94 20-143-8z" fill="#faf3de" stroke="#b69457" stroke-width="2"/><path d="M130 116l-9 69m37-65-12 68m42-59-15 57m41-53-15 48" stroke="#d5bc83" stroke-width="2"/><circle cx="253" cy="147" r="33" fill="#f3cf35" stroke="#9d7f24" stroke-width="2"/><circle cx="253" cy="147" r="26" fill="#fff2a8"/><path d="M253 121v52m-26-26h52m-44-18 36 36m0-36-36 36" stroke="#e0b721" stroke-width="2"/><path d="M96 157l-8-10m12 3 5-11m25 24 10-8m39 16 8-11m36-28 3-10m36 68 11 5m-20-3-5 13" stroke="#4f734d" stroke-width="5" stroke-linecap="round"/>`,
 'small-apple-turnover':`<ellipse cx="178" cy="194" rx="132" ry="57" fill="#ddcdb5"/><ellipse cx="178" cy="180" rx="132" ry="58" fill="#faf5e9" stroke="#173565" stroke-width="3"/><ellipse cx="178" cy="180" rx="108" ry="40" fill="none" stroke="#b9a986"/><path d="M82 194l79-111 96 111q-84 28-175 0z" fill="#d8943b" stroke="#71482b" stroke-width="3"/><path d="M89 187l72-95 86 95q-75 24-158 0z" fill="#e7b568"/><path d="M116 177l42-48m-16 49 38-43m-9 47 32-35" stroke="#a96928" stroke-width="5" stroke-linecap="round"/><path d="M98 197l2-10m17 14 1-10m18 14v-11m18 12v-10m18 11v-11m18 10v-11m18 7-1-11m18 6-2-10m16 5-3-10" stroke="#965b2a" stroke-width="2"/><path d="M264 139q-19-28-38-3-6 24 17 40 22 4 27-18z" fill="#ae3444"/><path d="M247 140l2-20m0 6q20-15 27 0-12 10-27 0" stroke="#526647" fill="#738457" stroke-width="3"/>`
 };
 function illustration(id){return `<svg viewBox="0 0 360 280" class="inn-food-art" aria-hidden="true"><circle cx="180" cy="150" r="111" fill="#e6ddcd" opacity=".65"/>${art[id]||''}</svg>`;}
 function sourceRating(r){if(!Number.isFinite(r.source?.rating))return `<div class="recipe-source-rating"><span>${r.source?.kind==='literary'?t('המקור הספרותי','THE LITERARY SOURCE'):t('הבסיס למתכון','RECIPE BASIS')}</span>${r.source?.url?outside(r.source.url,r.source.publisher+' · '+r.source.name):''}<small>${h(r.ratingNote||r.source?.note||{he:'מקור למתכון',en:'Recipe source'})}</small></div>`;return `<div class="recipe-source-rating"><span>${t('הדירוג של מתכון המקור','ORIGINAL RECIPE RATING')}</span><b dir="ltr">${r.source.rating} / ${r.source.ratingMax} <i aria-hidden="true">★</i></b><small>${r.source.voteCount} ${t('הצבעות','votes')} · ${t('נבדק 10.10.2026','checked 10 Oct 2026')}</small>${outside(r.source.url,r.source.publisher+' · '+r.source.name)}<small>${t('דירוג הקוראים באתר המקור.','Reader rating on the source website.')}</small></div>`;}
 function recipe(r,i){return `<article class="inn-recipe" id="recipe-${esc(r.id)}" tabindex="-1" data-recipe-card="${esc(r.id)}"><div class="recipe-heading"><div><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${h(r.course)}</div><h2>${h(r.title)}</h2><p class="recipe-modern">${h(r.modernDishLabel)}</p><div class="recipe-facts"><span>${h(r.servings)}</span><span>${t('כ־','About ')}${r.minutes} ${t('דקות בסך הכול','minutes total')}</span><span>${r.activeMinutes} ${t('דקות עבודה','minutes active')}</span></div>${r.timeNote?`<p class="recipe-time-note">${h(r.timeNote)}</p>`:''}</div><div class="recipe-dish-art">${illustration(r.id)}</div></div><div class="recipe-literary"><div><span>${t('אצל הוגו','IN THE NOVEL')}</span><h3>${h(r.novelFoodLabel)}</h3><p>${h(r.book)}</p></div><div class="recipe-chapter">${outside(r.book.url,{he:'הוגו · '+r.book.reference,en:'Hugo · '+r.book.reference})}${r.book.secondaryUrl?outside(r.book.secondaryUrl,t('גם בארוחת הבישוף','Also at the bishop’s supper')):''}<small>${t('חלק · ספר · פרק. קישור לטקסט המלא עשוי לחשוף עלילה.','Part · book · chapter. Full-text links may reveal plot.')}</small></div></div>${r.equipment?`<p class="recipe-equipment"><b>${t('כלים: ','Equipment: ')}</b>${h(r.equipment)}</p>`:''}<div class="recipe-workbench"><section class="recipe-ingredients"><h3>${t('מה צריך','What you need')}</h3><ul>${r.ingredients[lang].map((v,j)=>`<li><label><input type="checkbox" class="recipe-check" ${checkAttrs(r.id,'ingredient',j)} aria-label="${h(v)}"><span>${h(v)}</span></label></li>`).join('')}</ul><p class="recipe-pantry">${h(r.availability)}</p></section><section class="recipe-method"><h3>${t('מה עושים','What to do')}</h3><ol>${r.steps[lang].map((v,j)=>`<li><label><input type="checkbox" class="recipe-check" ${checkAttrs(r.id,'step',j)}><span><b aria-hidden="true">${j+1}</b>${h(v)}</span></label></li>`).join('')}</ol><div class="recipe-adaptation"><b>${t('ההתאמה שלנו','OUR ADAPTATION')}</b><p>${h(r.adaptation)}</p></div></section></div>${r.variation?`<aside class="recipe-variation"><h3>${h(r.variation.title)}</h3><p>${h(r.variation)}</p>${r.variation.recipeId?`<a class="text-link" href="#recipe-${esc(r.variation.recipeId)}" data-recipe-jump="${esc(r.variation.recipeId)}">${h(r.variation.linkLabel||{he:'למתכון המקושר',en:'Go to the linked recipe'})} →</a>`:''}</aside>`:''}<div class="recipe-bottom">${sourceRating(r)}<div class="recipe-practical"><p><b>${t('אלרגנים: ','Allergens: ')}</b>${h(r.allergens)}</p><p><b>${r.cookMinutes?t('בישול: ','Cooking: '):t('אפייה: ','Baking: ')}</b>${h(r.cookMinutes||r.ovenMinutes)} ${t('דקות','minutes')}${r.coolingMinutes?` · ${t('המתנה וקירור: ','Resting/cooling: ')}${h(r.coolingMinutes)} ${t('דקות','minutes')}`:''}</p>${r.safety?`<p class="recipe-safety-note">${h(r.safety)} ${r.safety.url?outside(r.safety.url,t('מקור להנחיית הבטיחות','Safety source')):''}</p>`:''}${r.safetyUrl?outside(r.safetyUrl,t('טמפרטורות בישול בטוחות · FoodSafety.gov','Safe cooking temperatures · FoodSafety.gov')):''}<button class="btn secondary" data-recipe-print="${esc(r.id)}">${t('להדפיס את המתכון','Print this recipe')} →</button></div></div><p class="recipe-test-note">${r.source.kind==='literary'?t('מקור ספרותי: ','Literary source: '):t('מתכון המקור: ','Original recipe by ')}${esc(r.source.author)}.</p></article>`;}
 function page(locale){if(document.body)delete document.body.dataset.printRecipe;lang=locale;const d=D();if(!d)return '';return `<div class="wrap inn-page"><section class="inn-welcome"><div class="inn-sign"><span>${t('ברוכים הבאים','YOU ARE MOST WELCOME')}</span><h2>Au Sergent<br>de Waterloo</h2><i>${t('מונפרמיי · הפונדק של טנארדייה','MONTFERMEIL · THE THÉNARDIERS’ INN')}</i><div class="inn-sign-rule"></div><p>${t('האירוח מפוקפק.<br>במטבח שלכם, אתם בעלי הבית.','The hospitality is questionable.<br>In your kitchen, you’re in charge.')}</p><small>${h(d.inn)} ${outside(d.inn.url,d.inn.reference)}</small></div><div class="inn-invitation"><div class="eyebrow">${t('ארוחת ערב, עם הערת שוליים','DINNER, WITH A FOOTNOTE')}</div><h2>${t('קחו כיסא.<br>את החשבון, כדאי לבדוק.','Pull up a chair.<br>Keep an eye on the bill.')}</h2><p>${h(d.intro)}</p><div class="inn-menu-preview">${d.recipes.map((r,i)=>`<a href="#recipe-${esc(r.id)}" data-recipe-jump="${esc(r.id)}"><span>0${i+1}</span><div><b>${h(r.title)}</b><small>${h(r.course)} · ${t('כ־','about ')}${r.minutes} ${t('דקות','min')}</small></div><em aria-hidden="true">↗</em></a>`).join('')}</div></div></section><div class="inn-editorial-note"><b>${t('מן הספר אל השולחן','FROM THE BOOK TO THE TABLE')}</b><p>${h(d.accuracyNote)}</p><p>${h(d.carbNote)}</p><small>${t('מתכוני המקור פתוחים לקריאה, אך אינם ברישיון חופשי. ההוראות והאיורים כאן נכתבו ונוצרו עבור המדריך.','Source recipes are free to read, not openly licensed. The instructions and illustrations here were created for this guide.')}</small></div><section class="inn-before-cooking"><div><h2>${t('לפני שמדליקים תנור','Before the oven goes on')}</h2><ul>${d.servingPlan[lang].map(x=>`<li>${h(x)}</li>`).join('')}</ul></div><div><p>${h(d.timingNote)}</p><p>${t('אפשר לסמן מצרכים ושלבים. הסימונים נשארים בביקור הזה, גם במעבר שפה; רענון הדף מאפס אותם. הם אינם נשמרים לביקור הבא או נשלחים לשום מקום.','Tick ingredients and steps as you go. Checks last for this visit, including language changes; reloading resets them. They are not saved for future visits or sent anywhere.')}</p><button class="btn secondary" data-menu-print>${t('להדפיס את כל התפריט','Print the whole menu')} →</button></div></section>${d.recipes.map(recipe).join('')}<aside class="inn-safety"><h2>${t('סוגרים מטבח כמו שצריך','Close the kitchen properly')}</h2><p>${h(d.safety)}</p><div class="source-links">${d.safety.urls.map((u,i)=>outside(u,i?t('FoodSafety.gov: טמפרטורות בטוחות','FoodSafety.gov: safe temperatures'):t('USDA: שמירת שאריות','USDA: leftovers'))).join('')}</div></aside><div class="inn-checkout"><span class="eyebrow">${t('החשבון, בבקשה','THE BILL, PLEASE')}</span><h2>${t('על הסיפור כבר שילמנו בדמעות.<br>על הכלים תצטרכו לדבר ביניכם.','The story cost us a few tears.<br>The washing-up is between you.')}</h2><a href="/${lang}/places/?place=montfermeil" data-place-essay="montfermeil" class="btn">${t('למונפרמיי שמחוץ למטבח','Visit Montfermeil beyond the kitchen')} →</a></div></div>`;}
 function handle(e){const a=e.target.closest('a[data-recipe-jump]');if(a?.dataset?.recipeJump&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();const target=document.getElementById('recipe-'+a.dataset.recipeJump);target?.focus({preventScroll:true});target?.scrollIntoView({block:'start',behavior:'instant'});return true;}const b=e.target.closest('button');if(!b)return false;if(b.dataset.recipePrint||b.hasAttribute?.('data-menu-print')){if(b.dataset.recipePrint)document.body.dataset.printRecipe=b.dataset.recipePrint;else delete document.body.dataset.printRecipe;window.print();return true;}return false;}
 window.addEventListener('afterprint',()=>{delete document.body.dataset.printRecipe});
 function change(e){const key=e.target?.dataset?.recipeCheck;if(!key)return false;if(e.target.checked)checked.add(key);else checked.delete(key);return true;}
 window.InnKitchen={page,handle,change};
})();
